Dataspatium.assets.register("presets/ids/SE-Dataspatium_Avfallshantering.ids","text","<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!-- SPDX-License-Identifier: LicenseRef-PolyForm-Strict-1.0.0 -->\n<ids:ids xmlns:ids=\"http://standards.buildingsmart.org/IDS\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://standards.buildingsmart.org/IDS http://standards.buildingsmart.org/IDS/1.0/ids.xsd\">\n  <ids:info>\n    <ids:title>Avfallshantering: material, mängder och produktdata</ids:title>\n    <ids:copyright>Dataspatium</ids:copyright>\n    <ids:version>1.0</ids:version>\n    <ids:description>Det som materialinventeringen i Dataspatium behöver ur en IFC4- eller IFC4.3-modell som underlag för avfallshanteringsplanen enligt PBL 10 kap. 8 a §: material med kategori för avfallsfraktionerna, basmängder för mängderna och produktdata för de byggprodukter som kan återanvändas. IFC2X3 saknar materialkategori, mallar för basmängder och GTIN.</ids:description>\n    <ids:date>2026-11-12</ids:date>\n    <ids:purpose>Underlag för avfallshanteringsplanen (PBL 10 kap. 8 a §)</ids:purpose>\n  </ids:info>\n  <ids:specifications>\n    <ids:specification name=\"Material med kategori\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"AH-01\" description=\"Varje byggdel har ett material med en kategori ur IFC:s rekommenderade värden, så att avfallsfraktionen enligt avfallsförordningen 3 kap. 10 § kan läsas ur modellen. Sammansatta byggdelar (tak, trappor, ramper, glasfasader) prövas i sina delar.\" instructions=\"Ge materialet (IfcMaterial) en kategori i Category: concrete, steel, aluminium, block, brick, stone, wood, glass, gypsum, plastic eller earth. Kontrollen godkänner när minst ett av byggdelens material har en sådan kategori; inventeringen i appen visar varje skikt.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCWALL\"/>\n              <xs:enumeration value=\"IFCWALLSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCSLAB\"/>\n              <xs:enumeration value=\"IFCBEAM\"/>\n              <xs:enumeration value=\"IFCCOLUMN\"/>\n              <xs:enumeration value=\"IFCMEMBER\"/>\n              <xs:enumeration value=\"IFCPLATE\"/>\n              <xs:enumeration value=\"IFCFOOTING\"/>\n              <xs:enumeration value=\"IFCPILE\"/>\n              <xs:enumeration value=\"IFCSTAIRFLIGHT\"/>\n              <xs:enumeration value=\"IFCRAMPFLIGHT\"/>\n              <xs:enumeration value=\"IFCRAILING\"/>\n              <xs:enumeration value=\"IFCCOVERING\"/>\n              <xs:enumeration value=\"IFCDOOR\"/>\n              <xs:enumeration value=\"IFCWINDOW\"/>\n              <xs:enumeration value=\"IFCBUILDINGELEMENTPROXY\"/>\n              <xs:enumeration value=\"IFCCHIMNEY\"/>\n              <xs:enumeration value=\"IFCSHADINGDEVICE\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:material cardinality=\"required\" instructions=\"Material med kategori (IfcMaterial.Category).\">\n          <ids:value>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"[Cc]oncrete|[Ss]teel|[Aa]luminium|[Bb]lock|[Bb]rick|[Ss]tone|[Ww]ood|[Gg]lass|[Gg]ypsum|[Pp]lastic|[Ee]arth\"/>\n            </xs:restriction>\n          </ids:value>\n        </ids:material>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Material med kategori (IFC4:s StandardCase)\" ifcVersion=\"IFC4\" identifier=\"AH-01b\" description=\"Varje byggdel har ett material med en kategori ur IFC:s rekommenderade värden, så att avfallsfraktionen enligt avfallsförordningen 3 kap. 10 § kan läsas ur modellen. Sammansatta byggdelar (tak, trappor, ramper, glasfasader) prövas i sina delar.\" instructions=\"Ge materialet (IfcMaterial) en kategori i Category: concrete, steel, aluminium, block, brick, stone, wood, glass, gypsum, plastic eller earth. Kontrollen godkänner när minst ett av byggdelens material har en sådan kategori; inventeringen i appen visar varje skikt.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCWALLELEMENTEDCASE\"/>\n              <xs:enumeration value=\"IFCSLABSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCSLABELEMENTEDCASE\"/>\n              <xs:enumeration value=\"IFCBEAMSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCCOLUMNSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCMEMBERSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCPLATESTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCDOORSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCWINDOWSTANDARDCASE\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:material cardinality=\"required\" instructions=\"Material med kategori (IfcMaterial.Category).\">\n          <ids:value>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"[Cc]oncrete|[Ss]teel|[Aa]luminium|[Bb]lock|[Bb]rick|[Ss]tone|[Ww]ood|[Gg]lass|[Gg]ypsum|[Pp]lastic|[Ee]arth\"/>\n            </xs:restriction>\n          </ids:value>\n        </ids:material>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Basmängd: volym\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"AH-02\" description=\"Byggdelen har sin basmängd för volym (NetVolume eller GrossVolume) i klassens Qto-uppsättning, för mängden och massan per material.\" instructions=\"Skriv basmängderna (Qto_…BaseQuantities) med netto- eller bruttovolym.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCWALL\"/>\n              <xs:enumeration value=\"IFCWALLSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCSLAB\"/>\n              <xs:enumeration value=\"IFCBEAM\"/>\n              <xs:enumeration value=\"IFCCOLUMN\"/>\n              <xs:enumeration value=\"IFCMEMBER\"/>\n              <xs:enumeration value=\"IFCPLATE\"/>\n              <xs:enumeration value=\"IFCFOOTING\"/>\n              <xs:enumeration value=\"IFCSTAIRFLIGHT\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:property dataType=\"IFCVOLUMEMEASURE\" cardinality=\"required\" instructions=\"Netto- eller bruttovolym i klassens basmängder.\">\n          <ids:propertySet>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"Qto_(Wall|Slab|Beam|Column|Member|Plate|Footing|StairFlight)BaseQuantities\"/>\n            </xs:restriction>\n          </ids:propertySet>\n          <ids:baseName>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"(Net|Gross)Volume\"/>\n            </xs:restriction>\n          </ids:baseName>\n        </ids:property>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Basmängd: volym (IFC4:s StandardCase)\" ifcVersion=\"IFC4\" identifier=\"AH-02b\" description=\"Byggdelen har sin basmängd för volym (NetVolume eller GrossVolume) i klassens Qto-uppsättning, för mängden och massan per material.\" instructions=\"Skriv basmängderna (Qto_…BaseQuantities) med netto- eller bruttovolym.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCWALLELEMENTEDCASE\"/>\n              <xs:enumeration value=\"IFCSLABSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCSLABELEMENTEDCASE\"/>\n              <xs:enumeration value=\"IFCBEAMSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCCOLUMNSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCMEMBERSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCPLATESTANDARDCASE\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:property dataType=\"IFCVOLUMEMEASURE\" cardinality=\"required\" instructions=\"Netto- eller bruttovolym i klassens basmängder.\">\n          <ids:propertySet>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"Qto_(Wall|Slab|Beam|Column|Member|Plate|Footing|StairFlight)BaseQuantities\"/>\n            </xs:restriction>\n          </ids:propertySet>\n          <ids:baseName>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"(Net|Gross)Volume\"/>\n            </xs:restriction>\n          </ids:baseName>\n        </ids:property>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Basmängd: area\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"AH-03\" description=\"Dörrar, fönster, beklädnader, tak och glasfasader har sin basmängd för area (Area, NetArea, GrossArea eller sidoarean) i klassens Qto-uppsättning.\" instructions=\"Skriv basmängderna (Qto_…BaseQuantities, för glasfasader Qto_CurtainWallQuantities) med arean.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCDOOR\"/>\n              <xs:enumeration value=\"IFCWINDOW\"/>\n              <xs:enumeration value=\"IFCCOVERING\"/>\n              <xs:enumeration value=\"IFCROOF\"/>\n              <xs:enumeration value=\"IFCCURTAINWALL\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:property dataType=\"IFCAREAMEASURE\" cardinality=\"required\" instructions=\"Arean i klassens basmängder.\">\n          <ids:propertySet>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"Qto_(Door|Window|Covering|Roof)BaseQuantities|Qto_CurtainWallQuantities\"/>\n            </xs:restriction>\n          </ids:propertySet>\n          <ids:baseName>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"Area|NetArea|GrossArea|NetSideArea|GrossSideArea\"/>\n            </xs:restriction>\n          </ids:baseName>\n        </ids:property>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Basmängd: area (IFC4:s StandardCase)\" ifcVersion=\"IFC4\" identifier=\"AH-03b\" description=\"Dörrar, fönster, beklädnader, tak och glasfasader har sin basmängd för area (Area, NetArea, GrossArea eller sidoarean) i klassens Qto-uppsättning.\" instructions=\"Skriv basmängderna (Qto_…BaseQuantities, för glasfasader Qto_CurtainWallQuantities) med arean.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCDOORSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCWINDOWSTANDARDCASE\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:property dataType=\"IFCAREAMEASURE\" cardinality=\"required\" instructions=\"Arean i klassens basmängder.\">\n          <ids:propertySet>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"Qto_(Door|Window|Covering|Roof)BaseQuantities|Qto_CurtainWallQuantities\"/>\n            </xs:restriction>\n          </ids:propertySet>\n          <ids:baseName>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"Area|NetArea|GrossArea|NetSideArea|GrossSideArea\"/>\n            </xs:restriction>\n          </ids:baseName>\n        </ids:property>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Produktdata på dörrar, fönster och installationer\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"AH-04\" description=\"Dörrar, fönster och installationer har produktdata för återbruk: tillverkare och modell i Pset_ManufacturerTypeInformation, helst på typen, och GTIN i GlobalTradeItemNumber när det finns.\" instructions=\"Ange Manufacturer och ModelLabel ur produktens dokumentation. Ange GTIN bara när tillverkaren har gett det (8, 12, 13 eller 14 siffror); hitta aldrig på ett. Serienummer och streckkod hör till Pset_ManufacturerOccurrence på byggdelen.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCDOOR\"/>\n              <xs:enumeration value=\"IFCWINDOW\"/>\n              <xs:enumeration value=\"IFCAIRTERMINAL\"/>\n              <xs:enumeration value=\"IFCAIRTERMINALBOX\"/>\n              <xs:enumeration value=\"IFCSANITARYTERMINAL\"/>\n              <xs:enumeration value=\"IFCWASTETERMINAL\"/>\n              <xs:enumeration value=\"IFCSTACKTERMINAL\"/>\n              <xs:enumeration value=\"IFCFIRESUPPRESSIONTERMINAL\"/>\n              <xs:enumeration value=\"IFCLIGHTFIXTURE\"/>\n              <xs:enumeration value=\"IFCLAMP\"/>\n              <xs:enumeration value=\"IFCOUTLET\"/>\n              <xs:enumeration value=\"IFCSPACEHEATER\"/>\n              <xs:enumeration value=\"IFCCOOLEDBEAM\"/>\n              <xs:enumeration value=\"IFCBOILER\"/>\n              <xs:enumeration value=\"IFCBURNER\"/>\n              <xs:enumeration value=\"IFCCHILLER\"/>\n              <xs:enumeration value=\"IFCCOIL\"/>\n              <xs:enumeration value=\"IFCCONDENSER\"/>\n              <xs:enumeration value=\"IFCCOOLINGTOWER\"/>\n              <xs:enumeration value=\"IFCEVAPORATOR\"/>\n              <xs:enumeration value=\"IFCEVAPORATIVECOOLER\"/>\n              <xs:enumeration value=\"IFCHEATEXCHANGER\"/>\n              <xs:enumeration value=\"IFCAIRTOAIRHEATRECOVERY\"/>\n              <xs:enumeration value=\"IFCHUMIDIFIER\"/>\n              <xs:enumeration value=\"IFCUNITARYEQUIPMENT\"/>\n              <xs:enumeration value=\"IFCENGINE\"/>\n              <xs:enumeration value=\"IFCELECTRICGENERATOR\"/>\n              <xs:enumeration value=\"IFCELECTRICMOTOR\"/>\n              <xs:enumeration value=\"IFCTRANSFORMER\"/>\n              <xs:enumeration value=\"IFCPUMP\"/>\n              <xs:enumeration value=\"IFCFAN\"/>\n              <xs:enumeration value=\"IFCCOMPRESSOR\"/>\n              <xs:enumeration value=\"IFCVALVE\"/>\n              <xs:enumeration value=\"IFCDAMPER\"/>\n              <xs:enumeration value=\"IFCFLOWMETER\"/>\n              <xs:enumeration value=\"IFCSWITCHINGDEVICE\"/>\n              <xs:enumeration value=\"IFCPROTECTIVEDEVICE\"/>\n              <xs:enumeration value=\"IFCELECTRICTIMECONTROL\"/>\n              <xs:enumeration value=\"IFCELECTRICDISTRIBUTIONBOARD\"/>\n              <xs:enumeration value=\"IFCTANK\"/>\n              <xs:enumeration value=\"IFCELECTRICFLOWSTORAGEDEVICE\"/>\n              <xs:enumeration value=\"IFCFILTER\"/>\n              <xs:enumeration value=\"IFCINTERCEPTOR\"/>\n              <xs:enumeration value=\"IFCDUCTSILENCER\"/>\n              <xs:enumeration value=\"IFCSENSOR\"/>\n              <xs:enumeration value=\"IFCACTUATOR\"/>\n              <xs:enumeration value=\"IFCALARM\"/>\n              <xs:enumeration value=\"IFCCONTROLLER\"/>\n              <xs:enumeration value=\"IFCUNITARYCONTROLELEMENT\"/>\n              <xs:enumeration value=\"IFCELECTRICAPPLIANCE\"/>\n              <xs:enumeration value=\"IFCAUDIOVISUALAPPLIANCE\"/>\n              <xs:enumeration value=\"IFCCOMMUNICATIONSAPPLIANCE\"/>\n              <xs:enumeration value=\"IFCMEDICALDEVICE\"/>\n              <xs:enumeration value=\"IFCSOLARDEVICE\"/>\n              <xs:enumeration value=\"IFCTRANSPORTELEMENT\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:property dataType=\"IFCLABEL\" cardinality=\"required\" instructions=\"Tillverkaren.\">\n          <ids:propertySet><ids:simpleValue>Pset_ManufacturerTypeInformation</ids:simpleValue></ids:propertySet>\n          <ids:baseName><ids:simpleValue>Manufacturer</ids:simpleValue></ids:baseName>\n        </ids:property>\n        <ids:property dataType=\"IFCLABEL\" cardinality=\"required\" instructions=\"Modellens namn.\">\n          <ids:propertySet><ids:simpleValue>Pset_ManufacturerTypeInformation</ids:simpleValue></ids:propertySet>\n          <ids:baseName><ids:simpleValue>ModelLabel</ids:simpleValue></ids:baseName>\n        </ids:property>\n        <ids:property dataType=\"IFCIDENTIFIER\" cardinality=\"optional\" instructions=\"GTIN, när tillverkaren har gett det: 8, 12, 13 eller 14 siffror.\">\n          <ids:propertySet><ids:simpleValue>Pset_ManufacturerTypeInformation</ids:simpleValue></ids:propertySet>\n          <ids:baseName><ids:simpleValue>GlobalTradeItemNumber</ids:simpleValue></ids:baseName>\n          <ids:value>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"[0-9]{8}|[0-9]{12,14}\"/>\n            </xs:restriction>\n          </ids:value>\n        </ids:property>\n      </ids:requirements>\n    </ids:specification>\n    <ids:specification name=\"Produktdata på dörrar och fönster (IFC4:s StandardCase)\" ifcVersion=\"IFC4\" identifier=\"AH-04b\" description=\"Dörrar, fönster och installationer har produktdata för återbruk: tillverkare och modell i Pset_ManufacturerTypeInformation, helst på typen, och GTIN i GlobalTradeItemNumber när det finns.\" instructions=\"Ange Manufacturer och ModelLabel ur produktens dokumentation. Ange GTIN bara när tillverkaren har gett det (8, 12, 13 eller 14 siffror); hitta aldrig på ett. Serienummer och streckkod hör till Pset_ManufacturerOccurrence på byggdelen.\">\n      <ids:applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <ids:entity>\n          <ids:name>\n            <xs:restriction base=\"xs:string\">\n              <xs:enumeration value=\"IFCDOORSTANDARDCASE\"/>\n              <xs:enumeration value=\"IFCWINDOWSTANDARDCASE\"/>\n            </xs:restriction>\n          </ids:name>\n        </ids:entity>\n      </ids:applicability>\n      <ids:requirements>\n        <ids:property dataType=\"IFCLABEL\" cardinality=\"required\" instructions=\"Tillverkaren.\">\n          <ids:propertySet><ids:simpleValue>Pset_ManufacturerTypeInformation</ids:simpleValue></ids:propertySet>\n          <ids:baseName><ids:simpleValue>Manufacturer</ids:simpleValue></ids:baseName>\n        </ids:property>\n        <ids:property dataType=\"IFCLABEL\" cardinality=\"required\" instructions=\"Modellens namn.\">\n          <ids:propertySet><ids:simpleValue>Pset_ManufacturerTypeInformation</ids:simpleValue></ids:propertySet>\n          <ids:baseName><ids:simpleValue>ModelLabel</ids:simpleValue></ids:baseName>\n        </ids:property>\n        <ids:property dataType=\"IFCIDENTIFIER\" cardinality=\"optional\" instructions=\"GTIN, när tillverkaren har gett det: 8, 12, 13 eller 14 siffror.\">\n          <ids:propertySet><ids:simpleValue>Pset_ManufacturerTypeInformation</ids:simpleValue></ids:propertySet>\n          <ids:baseName><ids:simpleValue>GlobalTradeItemNumber</ids:simpleValue></ids:baseName>\n          <ids:value>\n            <xs:restriction base=\"xs:string\">\n              <xs:pattern value=\"[0-9]{8}|[0-9]{12,14}\"/>\n            </xs:restriction>\n          </ids:value>\n        </ids:property>\n      </ids:requirements>\n    </ids:specification>\n  </ids:specifications>\n</ids:ids>\n");
